/bin/bash -lc "python3 - <<'PY'
import os, socket, urllib.request, importlib.util
print('Python SDK installed:', importlib.util.find_spec('assemblyai') is not None)
for k,v in os.environ.items():
 if any(x in k.lower() for x in ['proxy','network']): print(k, v)
for host in ['api.assemblyai.com','www.assemblyai.com','pypi.org']:
 try: print(host, socket.getaddrinfo(host,443)[0][4])
 except Exception as e: print(type(e).__name__,str(e))
try:
 with urllib.request.urlopen('https://api.assemblyai.com/v2/transcript', timeout=10) as r: print(r.status)
except Exception as e: print(type(e).__name__,str(e))
PY"

