/bin/bash -lc "python3 - <<'PY'
import urllib.request
for i,u in enumerate(['https://assemblyai.com/docs/api-reference/transcripts/submit','https://api.assemblyai.com/v2/openapi.json','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/types.py']):
 try:
  r=urllib.request.urlopen(u,timeout=15); d=r.read(); open('/tmp/assemblyai-doc-'+str(i),'wb').write(d); print(i,r.status,len(d))
 except Exception as e: print(i,type(e).__name__,str(e))
PY"

